/// <summary>
/// Helper class to complete the purchase order processes.
/// </summary>
public class METPurchaseOrderProcessHelper
{
}

Method.Source:
/// <summary>
/// Substitute the reference PO line from a substituted sales line when done through IOM.
/// </summary>
/// <param name = "_salesLine">Sales line</param>
public static void cancelPurchLineFromSalesLine(SalesLine _salesLine)
{
    PurchLine purchLineExisting;

    purchLineExisting = METPurchaseOrderProcessHelper::getExistingPurchLine(_salesLine);

    if (purchLineExisting.RecId)
    {
        ttsbegin;
        purchLineExisting.RemainInventPhysical       = 0;
        purchLineExisting.RemainPurchPhysical        = 0;
        purchLineExisting.PdsCWRemainInventPhysical  = 0;

        purchLineExisting.update();
        ttscommit;
    }
}

/// <summary>
/// Copy the new sales line (After substituted from IOM) to a new purch line on the reference PO.
/// </summary>
/// <param name = "_salesLineNew">Sales line</param>
/// <returns></returns>
public static PurchLine copyToNewLineFromNewSalesLine(SalesLine _salesLineNew)
{
    PurchTable              purchTable;
    PurchLine               purchLineNew, purchLineExisting;
    METPurchLine            metPurchLineNew, metPurchLineExisting;
    InventItemPurchSetup    purchSetup;

    purchTable              = PurchTable::find(_salesLineNew.METReplenishmentPOReference);
    purchLineExisting       = METPurchaseOrderProcessHelper::getExistingCancelledPurchLine(_salesLineNew);
    metPurchLineExisting    = purchLineExisting.metPurchLine();

    ttsbegin;
    buf2Buf(metPurchLineExisting, metPurchLineNew);

    metPurchLineExisting = METPurchLine::find(purchLineExisting.RecId, true);

    metPurchLineExisting.ChangeReasonCode = METVendParameters::find().POChangeReasonCode;;
    metPurchLineExisting.update();

    purchLineNew.initFromPurchTable(purchTable);
    purchLineNew.initFromPurchLine(purchLineExisting, true, true, true);

    purchLineNew.ItemId             = _salesLineNew.ItemId;
    purchLineNew.PackedExtensions   = conNull();

    [purchSetup, purchLineNew.PurchUnit] = 
        InventItemPurchSetup::METGetPurchUnit(purchLineNew.ItemId, purchLineNew.InventDimId);

    purchLineNew.itemIdChanged();
    purchLineNew.PurchQty = _salesLineNew.SalesQty;
    PurchLine::modifyPurchQty(purchLineNew, purchLineNew.inventDim(), false);

    //METPurchaseOrderProcessHelper::setNewMetPurchLine(metSalesLineNew, metSalesLine);

    purchLineNew.metPackMETPurchLine(metPurchLineNew);
    purchLineNew.LineAmount = 0;
    purchLineNew.PriceUnit  = 0;

    purchLineNew.createLine(true, false, false, false, false);

    ttscommit;

    METPurchaseOrderProcessHelper::confirmPurchaseOrder(purchTable.PurchId);

    return purchLineNew;
}

/// <summary>
/// Get the existing purchase order line which was cancelled at the time of sales line substitution through IOM.
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <param name = "_salesInventDim">Sales order inventory dimension</param>
/// <returns>Purchase order line</returns>
public static PurchLine getExistingCancelledPurchLine(SalesLine _salesLine)
{
    PurchLine   cancelledPurchLine, retPurchLine;
    InventDim   purchInventDim, salesInventDim;

    salesInventDim = InventDim::find(_salesLine.InventDimId);

    select firstonly cancelledPurchLine
        where cancelledPurchLine.PurchId == _salesLine.METReplenishmentPOReference
        && cancelledPurchLine.ItemId == _salesLine.ItemId
        && cancelledPurchLine.PurchUnit == _salesLine.SalesUnit
        && cancelledPurchLine.PurchStatus == PurchStatus::Canceled
            join purchInventDim
            where purchInventDim.inventBatchId == salesInventDim.inventBatchId
                && purchInventDim.InventSiteId == salesInventDim.InventSiteId
                && purchInventDim.InventLocationId == salesInventDim.InventLocationId
                && purchInventDim.wMSLocationId == salesInventDim.wMSLocationId;

    if (cancelledPurchLine.RecId)
    {
        retPurchLine = cancelledPurchLine;
    }

    return retPurchLine;
}

/// <summary>
/// Get the existing purchase order line which was cancelled at the time of sales line substitution through IOM.
/// </summary>
/// <param name = "_salesLine">Sales order line</param>
/// <param name = "_salesInventDim">Sales order inventory dimension</param>
/// <returns>Purchase order line</returns>
public static PurchLine getExistingPurchLine(SalesLine _salesLine)
{
    PurchLine   existingPurchLine, retPurchLine;
    InventDim   purchInventDim, salesInventDim;

    salesInventDim = InventDim::find(_salesLine.InventDimId);

    select firstonly existingPurchLine
        where existingPurchLine.PurchId == _salesLine.METReplenishmentPOReference
        && existingPurchLine.ItemId == _salesLine.ItemId
        && existingPurchLine.PurchUnit == _salesLine.SalesUnit
        && existingPurchLine.PurchStatus != PurchStatus::Canceled
            join purchInventDim
            where purchInventDim.inventBatchId == salesInventDim.inventBatchId
                && purchInventDim.InventSiteId == salesInventDim.InventSiteId
                && purchInventDim.InventLocationId == salesInventDim.InventLocationId
                && purchInventDim.wMSLocationId == salesInventDim.wMSLocationId;

    if (existingPurchLine.RecId)
    {
        retPurchLine = existingPurchLine;
    }

    return retPurchLine;
}

